from textual.app import App, ComposeResult
from textual.containers import Container
from textual.widgets import Button, Label
from textual.message import Message


class CustomWidget(Container):
    class ButtonPressed(Message):
        """Message sent when the button is pressed."""
        def __init__(self, button_text: str) -> None:
            super().__init__()
            self.button_text = button_text

    def compose(self) -> ComposeResult:
        yield Button("Send Message", id="send_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        self.post_message(self.ButtonPressed("Message from button!"))


class MyApp(App):
    def compose(self) -> ComposeResult:
        yield CustomWidget()
        yield Label("Waiting for message...", id="output")

    def on_custom_widget_button_pressed(self, message: CustomWidget.ButtonPressed) -> None:
        self.query_one("#output", Label).update(f"✓ {message.button_text}")


if __name__ == "__main__":
    MyApp().run()

